        function SafeGetValue(obj, path, defaultValue = 'N/A') {
            if (!obj) {
                return defaultValue;
            }

            const pathString = Array.isArray(path) ? path.join('.') : path;
            const pathParts = [];

            const regex = /([^.\[]+)|\[(\d+)\]/g;
            let match;
            while ((match = regex.exec(pathString)) !== null) {
                if (match[1] !== undefined) {
                    pathParts.push(match[1]);
                } else if (match[2] !== undefined) {
                    pathParts.push(parseInt(match[2]));
                }
            }

            let current = obj;
            for (let i = 0; i < pathParts.length; i++) {
                const key = pathParts[i];

                if (current === undefined || current === null) {
                    return defaultValue;
                }

                if (typeof current !== 'object') {
                    return defaultValue;
                }

                if (Array.isArray(current) && typeof key === 'number') {
                    if (key >= current.length) {
                        return defaultValue;
                    }
                    current = current[key];
                } else if (typeof key === 'string' && !current.hasOwnProperty(key)) {
                    return defaultValue;
                } else {
                    current = current[key];
                }
            }

            if (current === undefined || current === null) {
                return defaultValue;
            }

            if (Array.isArray(current)) {
                const result = current.length > 0 ? String(current[0]) : defaultValue;
                return result;
            }

            const result = String(current);
            return result;
        }

        function updateProgressBar(barId, value, max) {
            const bar = document.getElementById(barId);
            if (bar && max > 0) {
                const percentage = Math.max(0, Math.min(100, (value / max) * 100));
                bar.style.width = percentage + '%';
            }
        }

