                        </div>
                    `;
                    content.appendChild(card);
                }
            }

            modal.style.display = 'block';
        }

        function closeHostsModal() {
            document.getElementById('hostsModal').style.display = 'none';
        }

        window.onclick = function(event) {
            const modals = ['incarnationModal', 'abilitiesModal', 'hostAttributesModal', 'hostAppearanceModal', 'hostCapabilitiesModal', 'hostRelationshipsModal', 'hostInventoryModal', 'echoesModal', 'hostsModal'];
            modals.forEach(modalId => {
                const modal = document.getElementById(modalId);
                if (event.target === modal) {
                    modal.style.display = 'none';
                }
            });
        };

        document.addEventListener('DOMContentLoaded', initDisplay);
    </script>
</body>
