            const hostIdentityInstruction = host.identity ? `'${host.identity}'` : "'基于宿主属性、标签和世界观生成一个具体的职业身份'";

            const trustSuspicion = {
                trust: getRandomInt(40, 60) + (host.tags.personality.some(p => p.name === '善良') ? 15 : 0) - (host.tags.personality.some(p => p.name === '谨慎' || p.name === '偏执狂') ? 20 : 0),
                suspicion: getRandomInt(15, 35) - (host.tags.personality.some(p => p.name === '乐天派') ? 10 : 0) + (host.tags.personality.some(p => p.name === '偏执狂') ? 25 : 0)
            };
            trustSuspicion.trust = Math.max(5, Math.min(95, trustSuspicion.trust));
            trustSuspicion.suspicion = Math.max(5, Math.min(95, trustSuspicion.suspicion));

            let updateBlock = `<UpdateVariable>\\n<Analysis>\\n- 所有user和world变量: Y\\n- 所有host变量: Y\\n</Analysis>\\n`;
            Object.entries(spirit).forEach(([key, value]) => {
                if(key === 'incarnation_form'){
                    Object.entries(value).forEach(([iKey, iValue]) => {
                        if(typeof iValue === 'object' && iKey === 'sexual_features') {
                            Object.entries(iValue).forEach(([sKey, sValue]) => updateBlock += `_.set('user.incarnation_form[0].sexual_features.${sKey}[0]', '${sValue}');\\n`);
                        } else {
                           updateBlock += `_.set('user.incarnation_form[0].${iKey}[0]', '${iValue}');\\n`;
                        }
                    });
                } else {
                     updateBlock += `_.set('user.status.${key}[0]', '${value}');\\n`;
                }
            });
            updateBlock += `_.set('world.type[0]', '${world.type}');\\n`;
            Object.entries(world.laws).forEach(([key, value]) => updateBlock += `_.set('world.laws.${key}[0]', ${value});\\n`);

            updateBlock += `_.set('host.name[0]', ${hostNameInstruction});\\n`;
            updateBlock += `_.set('host.gender[0]', '${host.gender}');\\n`;
            updateBlock += `_.set('host.age[0]', ${host.age});\\n`;
            updateBlock += `_.set('host.identity[0]', ${hostIdentityInstruction});\\n`;
            updateBlock += `_.set('host.trust[0]', ${trustSuspicion.trust});\\n`;
            updateBlock += `_.set('host.suspicion[0]', ${trustSuspicion.suspicion});\\n`;
            Object.entries(host.attributes).forEach(([key, value]) => updateBlock += `_.set('host.attributes.${key}[0]', ${value});\\n`);
            Object.entries(host.morality.sevenEmotions).forEach(([key, value]) => updateBlock += `_.set('host.morality.sevenEmotions.${key}[0]', ${value});\\n`);
            Object.entries(host.morality.sixDesires).forEach(([key, value]) => updateBlock += `_.set('host.morality.sixDesires.${key}[0]', ${value});\\n`);
            updateBlock += `_.assign('host.tags.personality[0]', '$__META_EXTENSIBLE__$');\\n`;
            host.tags.personality.forEach(p => updateBlock += `_.assign('host.tags.personality[0]', ${JSON.stringify(p).replace(/'/g, "\\'")});\\n`);
            updateBlock += `_.assign('host.tags.quirks[0]', '$__META_EXTENSIBLE__$');\\n`;
            host.tags.quirks.forEach(q => updateBlock += `_.assign('host.tags.quirks[0]', ${JSON.stringify(q).replace(/'/g, "\\'")});\\n`);

            const completionList = `'core_description', 'disposition', 'current_thought', 'appearance.style', 'capabilities', 'relationships', 'inventory', 'core_desire', 'core_fear'，以及女性角色的'female_exclusive'部分`;
            updateBlock += `// 你必须基于以上数据，将宿主变量中的以下字段补充完整：${completionList}。\\n`;
            updateBlock += `</UpdateVariable>`;

            let userMessage = `启程：世界已定，宿主已选。请根据以下即将更新的变量，为我详细生成开局叙事。\\n开局处境：${host.situation || '请基于宿主身份和世界背景自由生成一个有趣的开局处境。'}\\n${updateBlock}`;
            triggerSlash(`/send ${userMessage.replace(/'/g, "\\'")}|/trigger`);
        };

        document.getElementById('btn-to-spirit-form').addEventListener('click', () => showScreen('screen-1'));
        document.getElementById('btn-back-to-intro').addEventListener('click', () => showScreen('screen-0'));
